import re
from typing import List, Tuple, Optional, Dict, Any
from dataclasses import dataclass
import logging

from SSI_V5.ingestion.result_models import MatchResult, ImportStatistics


# Konfiguracja logowania
logger = logging.getLogger(__name__)


class ParseError(Exception):
    """Wygodny wyjatek dla bledow parsowania"""
    pass


class ParserConfig:
    """Konfiguracja parsera"""
    
    # Separatory
    CSV_DELIMITER = ";"
    TEAM_SEPARATOR = " - "
    SCORE_SEPARATOR = ":"
    
    # Wzorce regex
    TEAM_NAME_PATTERN = r'^[A-Za-z0-9\s\-\.\'\(\)&]+$'
    SCORE_PATTERN = r'^\d+:\d+$'
    
    # Domyslne nazwy kolon
    DEFAULT_HEADERS = ["Nazwa", "Wynik"]
    
    @classmethod
    def get_team_separators(cls) -> List[str]:
        """Zwraca liste moliwych separatorow druzyn"""
        return [" - ", " vs ", " vs. ", " -", ":"]


@dataclass
class ParseResult:
    """Wynik parsowania pojedynczej linii"""
    success: bool
    match_result: Optional[MatchResult] = None
    error: Optional[str] = None
    line_number: int = 0
    raw_line: str = ""


class ResultParser:
    """
    Parser wynikow meczow z formatu CSV.
    
    Obsluguje:
    - Linie w formacie: "Arsenal - Chelsea;2:1"
    - rozne separatory druzyn
    - Walidacje i obsluge bledow
    """
    
    def __init__(self, config: Optional[ParserConfig] = None):
        """
        Inicjalizacja parsera.
        
        Args:
            config: Konfiguracja parsera (opcjonalnie)
        """
        self.config = config or ParserConfig()
        self.errors: List[str] = []
        self.warnings: List[str] = []
        self.stats = ImportStatistics()
    
    def parse_line(self, line: str, line_number: int = 0) -> ParseResult:
        """
        Parsuje pojedyncza linie CSV.
        
        Args:
            line: Linia tekstowa do sparsowania
            line_number: Numer linii (dla debugowania)
            
        Returns:
            ParseResult z wynikiem parsowania
        """
        line = line.strip()
        
        # Pomijamy puste linie i komentarze
        if not line or line.startswith('#'):
            return ParseResult(
                success=False,
                error="Empty or comment line",
                line_number=line_number,
                raw_line=line
            )
        
        # Dzielimy po separatorze CSV
        parts = line.split(self.config.CSV_DELIMITER)
        
        # Walidacja liczby kolon
        if len(parts) < 2:
            return ParseResult(
                success=False,
                error=f"Invalid CSV format: expected at least 2 columns, got {len(parts)}",
                line_number=line_number,
                raw_line=line
            )
        
        #Wyciagamy nazwe meczu i wynik
        match_name = parts[0].strip()
        score_str = parts[1].strip()
        
        # Parsowanie nazwy meczu
        try:
            home_team, away_team = self._parse_match_name(match_name)
        except ParseError as e:
            return ParseResult(
                success=False,
                error=f"Failed to parse match name: {str(e)}",
                line_number=line_number,
                raw_line=line
            )
        
        # Parsowanie wyniku
        try:
            home_goals, away_goals = self._parse_score(score_str)
        except ParseError as e:
            return ParseResult(
                success=False,
                error=f"Failed to parse score: {str(e)}",
                line_number=line_number,
                raw_line=line
            )
        
        # Tworzymy MatchResult
        match_result = MatchResult(
            home_team=home_team,
            away_team=away_team,
            home_goals=home_goals,
            away_goals=away_goals,
            source="wyniki.csv"
        )
        
        return ParseResult(
            success=True,
            match_result=match_result,
            line_number=line_number,
            raw_line=line
        )
    
    def parse_lines(self, lines: List[str]) -> Tuple[List[MatchResult], ImportStatistics]:
        """
        Parsuje liste linii CSV.
        
        Args:
            lines: Lista linii tekstowych
            
        Returns:
            Tuple: (lista MatchResult, statystyki)
        """
        results: List[MatchResult] = []
        stats = ImportStatistics()
        self.errors = []
        
        for i, line in enumerate(lines, 1):
            parse_result = self.parse_line(line, i)
            
            if parse_result.success and parse_result.match_result:
                results.append(parse_result.match_result)
                stats.loaded += 1
            else:
                if parse_result.error:
                    self.errors.append(f"Line {i}: {parse_result.error}")
                    stats.errors += 1
                else:
                    stats.skipped += 1
        
        return results, stats
    
    def parse_csv_content(self, content: str) -> Tuple[List[MatchResult], ImportStatistics]:
        """
        Parsuje cala zawartosc CSV.
        
        Args:
            content: Pelna zawartosc pliku CSV
            
        Returns:
            Tuple: (lista MatchResult, statystyki)
        """
        lines = content.split('\n')
        
        # Pomijamy naglowek jeśli istnieje
        if lines and self._is_header_line(lines[0]):
            lines = lines[1:]
        
        return self.parse_lines(lines)
    
    def _is_header_line(self, line: str) -> bool:
        """Sprawdza czy linia jest naglowkiem"""
        line = line.strip().lower()
        headers = [h.lower() for h in self.config.DEFAULT_HEADERS]
        
        # Sprawdzamy czy linia zawiera typowe naglowki
        for header in headers:
            if header in line:
                return True
        
        return False
    
    def _parse_match_name(self, match_name: str) -> Tuple[str, str]:
        """
        Parsuje nazwe meczu na druzyny.
        
        Obsluguje formaty:
        - "Arsenal - Chelsea"
        - "Arsenal vs Chelsea"
        - "Arsenal vs. Chelsea"
        - "Arsenal-Chelsea"
        
        Args:
            match_name: Nazwa meczu
            
        Returns:
            Tuple: (home_team, away_team)
            
        Raises:
            ParseError: Jesli nie mozna sparsowac
        """
        match_name = match_name.strip()
        
        if not match_name:
            raise ParseError("Match name is empty")
        
        # Próbujemy rożnych separatorów
        for separator in ParserConfig.get_team_separators():
            if separator in match_name:
                parts = match_name.split(separator)
                if len(parts) == 2:
                    home_team = parts[0].strip()
                    away_team = parts[1].strip()
                    
                    # Walidacja nazwy druzyny
                    if not self._is_valid_team_name(home_team):
                        logger.warning(f"Invalid home team name: {home_team}")
                    if not self._is_valid_team_name(away_team):
                        logger.warning(f"Invalid away team name: {away_team}")
                    
                    return home_team, away_team
        
        # Jesli subcaminy separator nie działa, próbujemy regex
        # Wz ordre: Drugi wyraz (opcjonalnie z temu) - Reszta
        match = re.match(r'^([^\s]+(?:\s+[^\s]+)*)\s+[-:vs\.]+\s+(.+)$', match_name, re.IGNORECASE)
        if match:
            return match.group(1).strip(), match.group(2).strip()
        
        raise ParseError(f"Cannot parse match name: {match_name}")
    
    def _is_valid_team_name(self, team_name: str) -> bool:
        """Waliduje nazwe druzyny"""
        if not team_name:
            return False
        
        # Dopuszczalny wzorzec: litery, cyfry, spacje, myślniki, kropki
        pattern = r'^[A-Za-z0-9\s\-\.\'\(\)&]+$'
        return bool(re.match(pattern, team_name))
    
    def _parse_score(self, score_str: str) -> Tuple[int, int]:
        """
        Parsuje wynik na gole.
        
        Obsluguje formaty:
        - "2:1"
        - "0:0"
        - "5:3"
        
        Args:
            score_str: String z wynikiem
            
        Returns:
            Tuple: (home_goals, away_goals)
            
        Raises:
            ParseError: Jesli nie mozna sparsowac
        """
        score_str = score_str.strip()
        
        if not score_str:
            raise ParseError("Score is empty")
        
        # Dzielimy po dwukropku
        if ':' not in score_str:
            raise ParseError(f"Invalid score format: {score_str}")
        
        parts = score_str.split(':')
        
        if len(parts) != 2:
            raise ParseError(f"Invalid score format: {score_str}")
        
        try:
            home_goals = int(parts[0].strip())
            away_goals = int(parts[1].strip())
        except ValueError:
            raise ParseError(f"Invalid goal count: {score_str}")
        
        # Walidacja wartości
        if home_goals < 0 or away_goals < 0:
            raise ParseError(f"Negative goals: {score_str}")
        
        # Ograniczenie rozsądnej liczby goli
        if home_goals > 20 or away_goals > 20:
            logger.warning(f"Unusually high score: {score_str}")
        
        return home_goals, away_goals
    
    def validate_match_result(self, match_result: MatchResult) -> bool:
        """
        Waliduje MatchResult.
        
        Args:
            match_result: Obiekt MatchResult do walidacji
            
        Returns:
            True jesli poprawny, False w przeciwnym razie
        """
        if not match_result.home_team:
            return False
        if not match_result.away_team:
            return False
        if match_result.home_goals < 0 or match_result.away_goals < 0:
            return False
        return True
    
    def get_errors(self) -> List[str]:
        """Zwraca liste bledow"""
        return self.errors.copy()
    
    def get_warnings(self) -> List[str]:
        """Zwraca liste ostrzezen"""
        return self.warnings.copy()
    
    def reset(self):
        """Resetuje stan parsera"""
        self.errors = []
        self.warnings = []
        self.stats = ImportStatistics()
